// Preset generate dalla formula dell'Item Compendium (Ch 6a). Solo dati numerici: nome, categoria, unità del prezzo,
// spell base, variazioni di livello, CL, prezzo, moltiplicatore, totale stampato.
// unit 'numen' = oggetti magici, armi e munizioni (livello × CL × prezzo × moltiplicatore, in numen).
// unit 'gp' = alchimia e veleni: gp per dose; la scorta privata costa 18 volte i gp in numen (stock).
// "excluded" = variazioni che il Compendio non conta nel livello finale.
// Incluse solo le formule che riproducono il totale stampato. Le voci Slaying sono inserite a mano dal testo.
export interface PresetMod { name: string; adj: number; }
export interface ItemPreset {
  name: string;
  category: 'magico' | 'alchimia' | 'munizione';
  unit: 'numen' | 'gp';
  base: { name: string; level: number };
  mods: PresetMod[];
  excluded: string[];
  cl: number;
  price: number;
  multiplier: number;
  total: number;
  stock: number | null;
  qualifier: string | null;
}

